    pub fn diagram_objects(&self) -> impl Iterator<Item = TypedRef<DiagramObject<'static>>> + '_ {
        self.0
            .get_all(attrs::identified_object::DiagramObjects)
            .iter()
            .filter_map(|s| s.value.as_reference())
            .map(|m| TypedRef::new(m.clone()))
    }

    /// Resolve every `DiagramObjects` through `dataset`, skipping unresolved references.
    pub fn diagram_objects_in<'d>(
        &self,
        dataset: &'d Dataset,
    ) -> impl Iterator<Item = DiagramObject<'d>> + 'd {
        let mrids: Vec<Mrid> = self
            .0
            .get_all(attrs::identified_object::DiagramObjects)
            .iter()
            .filter_map(|s| s.value.as_reference().cloned())
            .collect();
        mrids
            .into_iter()
            .filter_map(move |m| dataset.by_mrid(&m).map(|o| DiagramObject(o)))
    }

